journal.py.text:
"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def read_changes(records):
    """Validate and deduplicate change records.

    Returns a dict mapping change ID to ``{"id", "component", "units",
    "depends_on"}`` where ``depends_on`` is a frozenset of change IDs.
    Identical records collapse to one; conflicting records for an ID fail.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        deps = read_ids(row.get("depends_on", []))
        change = {"id": row["id"], "component": row["component"],
                  "units": row["units"], "depends_on": deps}
        known = changes.get(change["id"])
        if known is None:
            changes[change["id"]] = change
        elif (known["component"] != change["component"] or known["units"] != change["units"]
                or known["depends_on"] != deps):
            raise JournalError("conflicting-change")
    return changes


def read_ids(values):
    """Validate an array of nonempty string IDs and return it as a frozenset."""
    if not isinstance(values, list):
        raise JournalError("invalid-change")
    for value in values:
        if not isinstance(value, str) or not value:
            raise JournalError("invalid-change")
    return frozenset(values)


def read_applied(values):
    """Validate the persisted release journal and return it as a frozenset."""
    return read_ids(values)

