    ``values`` defaults to empty. Every entry must be a known, applied change
    ID; anything else is ``invalid-retain``.
    """
    if not isinstance(values, list):
        raise JournalError("invalid-retain")
    for value in values:
        if not isinstance(value, str) or not value or value not in applied:
