"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import FrozenError, PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Full deterministic topological order with lexicographic tie-breaking.

    Raises JournalError("unknown-dependency") for dependencies that name no
    known change, and JournalError("dependency-cycle") if a cycle exists.
    """
    for change in changes.values():
        for dep in change["depends_on"]:
            if dep not in changes:
                raise JournalError("unknown-dependency")
    remaining = {cid: len(change["depends_on"]) for cid, change in changes.items()}
    dependents = {cid: [] for cid in changes}
    for cid, change in changes.items():
        for dep in change["depends_on"]:
            dependents[dep].append(cid)
    ready = [cid for cid, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for dependent in dependents[cid]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def retained_dependencies(changes, kept):
    """Return every applied change that ``kept`` transitively requires.

    The full graph is already known to be acyclic and to have no unknown
    dependencies when this runs, and ``kept`` only holds applied IDs.
    """
    retained = set(kept)
    pending = list(kept)
    while pending:
        for dep in changes[pending.pop()]["depends_on"]:
            if dep not in retained:
                retained.add(dep)
                pending.append(dep)
    return retained


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        for cid in applied:
            if cid not in changes:
                raise JournalError("unknown-dependency")
        order = topological_order(changes)
        rollback = request["action"] == "rollback"
        retain = read_retain(request.get("retain", []), applied) if rollback else frozenset()
    except (PolicyError, FrozenError, JournalError) as exc:
        return failure(str(exc))
    if rollback:
        kept = retained_dependencies(changes, retain)
        actions = [cid for cid in reversed(order) if cid in applied and cid not in kept]
    else:
        actions = [cid for cid in order if cid not in applied]
    units = sum(changes[cid]["units"] for cid in actions)
    if not rollback and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

