"""Normalize release records at the input boundary.

Kept free of graph and policy knowledge: this module only decides whether input
is well formed and what a change's identity is. Unknown targets, cycles and
budgets belong to planner/policy, so their errors are never raised here.
"""


class JournalError(ValueError):
    pass


def id_list(value, code):
    """Validate an array of change IDs (dependencies, journal, retained IDs).

    Booleans are excluded on purpose because ``True`` is an ``int`` in Python and
    would otherwise pass a naive string/type check.
    """
    if not isinstance(value, list) or any(not isinstance(item, str) or not item for item in value):
        raise JournalError(code)
    return list(value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        # depends_on defaults to empty; malformed dependency input is a change error.
        depends_on = row.get("depends_on", [])
        changes.append({"id": row["id"], "component": row["component"], "units": row["units"],
                        "depends_on": id_list(depends_on, "invalid-change")})
    return changes


def read_applied(value):
    return id_list(value, "invalid-change")


def read_retain(value):
    # Retained IDs are a rollback-only selection, so their shape is reported with
    # the dedicated invalid-retain code. Whether each ID is actually applied is a
    # replay question and is answered in planner once the graph exists.
    return id_list(value, "invalid-retain")

