"""Compose policy and journal data into a plan."""

import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def replay(changes):
    """Collapse identical duplicate records and reject conflicting ones.

    Runs before units are counted and before the graph is built, so a repeated
    record is never billed twice and dependency edges always see one node per ID.
    Equality covers component, units and the dependency set, so the order in
    which dependencies were listed does not create a false conflict.
    """
    by_id = {}
    for row in changes:
        deps = frozenset(row["depends_on"])
        prior = by_id.get(row["id"])
        if prior is None:
            by_id[row["id"]] = {"component": row["component"], "units": row["units"], "deps": deps}
        elif prior != {"component": row["component"], "units": row["units"], "deps": deps}:
            raise JournalError("conflicting-change")
    return by_id


def apply_journal(graph, applied_ids):
    """Return the applied ID set after checking it against the graph."""
    applied = set()
    for change_id in applied_ids:
        # Replay data comes from the caller, so an ID the graph never knew about is
        # a broken journal rather than a no-op we could silently drop.
        if change_id not in graph:
            raise JournalError("unknown-dependency")
        applied.add(change_id)
    return applied


def topological_order(graph):
    """Full deterministic execution order: lexicographic tie-break among ready nodes.

    The order depends only on the deduplicated graph, never on the applied
    journal, so rollback can reverse exactly the order a plan would have used.
    """
    indegree = {}
    dependents = {change_id: [] for change_id in graph}
    for change_id, node in graph.items():
        for dep in node["deps"]:
            if dep not in graph:
                raise JournalError("unknown-dependency")
            indegree[change_id] = indegree.get(change_id, 0) + 1
            dependents[dep].append(change_id)
    for change_id in graph:
        indegree.setdefault(change_id, 0)
    ready = [change_id for change_id, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for child in dependents[current]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, child)
    # A partial order means the leftover nodes sit on a cycle; no plan may proceed.
    if len(order) != len(graph):
        raise JournalError("dependency-cycle")
    return order


def retained_ids(graph, applied, retain):
    """Applied IDs that must survive a rollback: the retained set plus its closure.

    A retained change stays, so everything it depends on must stay too, otherwise
    the surviving release would be internally inconsistent. Only applied IDs are
    kept; an unapplied dependency is already absent from the rollback and cannot
    be removed twice.
    """
    keep = set()
    pending = list(retain)
    while pending:
        current = pending.pop()
        if current in keep:
            continue
        # Retaining something the journal never applied is a caller mistake: we
        # cannot promise to keep a release entry that does not exist.
        if current not in applied:
            raise JournalError("invalid-retain")
        keep.add(current)
        pending.extend(dep for dep in graph[current]["deps"] if dep not in keep)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Policy runs first: environment freeze and budget shape must be decided
        # before change/graph validation so production never reports a graph error.
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied_ids = read_applied(request.get("applied", []))
        graph = replay(changes)
        applied = apply_journal(graph, applied_ids)
        order = topological_order(graph)
        # retain only selects what a rollback keeps; reading it on the plan path
        # would change G1 plan behaviour, so it stays inside this branch.
        if request["action"] == "rollback":
            retain = read_retain(request.get("retain", []))
            keep = retained_ids(graph, applied, retain)
            emitted = [change_id for change_id in reversed(order)
                       if change_id in applied and change_id not in keep]
        else:
            # Dependencies are already guaranteed by the graph, so any unapplied
            # entry in execution order is eligible once earlier ones are applied.
            emitted = [change_id for change_id in order if change_id not in applied]
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(graph[change_id]["units"] for change_id in emitted)
    if units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted, "units": units}

