"""Normalize release records at the input boundary."""

import heapq


class JournalError(ValueError):
    pass


def _is_units(value):
    return type(value) is int and value >= 1


def _read_id_list(value):
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
    return value


def _canonical(row):
    item_id = row.get("id")
    component = row.get("component")
    units = row.get("units")
    if (not isinstance(item_id, str) or not item_id
            or not isinstance(component, str) or not component
            or not _is_units(units)):
        raise JournalError("invalid-change")
    if "depends_on" in row:
        depends_on = _read_id_list(row["depends_on"])
    else:
        depends_on = []
    return {"id": item_id, "component": component, "units": units,
            "depends_on": frozenset(depends_on)}


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    by_id = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        change = _canonical(row)
        known = by_id.get(change["id"])
        if known is None:
            by_id[change["id"]] = change
        elif known != change:  # same id, different component/units/dependency set
            raise JournalError("conflicting-change")
    return [by_id[item_id] for item_id in sorted(by_id)]


def read_applied(records):
    if "applied" not in records:
        return frozenset()
    return frozenset(_read_id_list(records["applied"]))


def check_graph(changes, applied):
    """Validate dependency targets and journal identity before ordering."""
    known = {change["id"] for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")
    for item_id in applied:
        if item_id not in known:
            raise JournalError("unknown-dependency")


def order(changes, applied):
    """Deterministic topological order with lexicographic ID tie-breaking."""
    pending = {change["id"]: set(change["depends_on"]) for change in changes}
    children = {item_id: [] for item_id in pending}
    for item_id, targets in pending.items():
        for target in targets:
            children[target].append(item_id)
    ready = [item_id for item_id, targets in pending.items() if not targets]
    heapq.heapify(ready)
    ordered = []
    while ready:
        item_id = heapq.heappop(ready)
        ordered.append(item_id)
        for child in children[item_id]:
            remaining = pending[child]
            remaining.discard(item_id)
            if not remaining:
                heapq.heappush(ready, child)
        del pending[item_id]
    if len(ordered) != len(changes):
        raise JournalError("dependency-cycle")
    return ordered

