"""Compose policy and journal data into a plan."""
from journal import (JournalError, check_graph, order, read_applied,
                     read_changes, read_retain)
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _retain_closure(changes, applied, retain):
    """Applied changes kept by the retained IDs plus their applied dependencies."""
    needs = {change["id"]: set(change["depends_on"]) for change in changes}
    kept = set()
    stack = sorted(retain)
    while stack:
        item_id = stack.pop()
        if item_id in kept:
            continue
        kept.add(item_id)
        for target in needs[item_id]:
            if target in applied and target not in kept:
                stack.append(target)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        rule = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        retain = read_retain(request) if rule["action"] == "rollback" else frozenset()
        check_graph(changes, applied)
        sequence = order(changes, applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = {change["id"]: change["units"] for change in changes}
    if rule["action"] == "rollback":
        if not retain <= applied:
            return failure("invalid-retain")
        kept = _retain_closure(changes, applied, retain)
        actions = [item_id for item_id in reversed(sequence)
                   if item_id in applied and item_id not in kept]
        return {"status": "ok", "actions": actions,
                "units": sum(units[item_id] for item_id in actions)}
    actions = [item_id for item_id in sequence if item_id not in applied]
    emitted = sum(units[item_id] for item_id in actions)
    if emitted > rule["budget"]:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": emitted}

