planner.py.text:
"""Compose policy, journal data and the graph into plan/rollback actions.

Replay order is load-bearing for G2 error precedence:

1. request shape            -> invalid-request
2. environment + action     -> invalid-environment / unsupported-action / production-frozen
3. change records + graph   -> invalid-change, conflicting-change, unknown-dependency, dependency-cycle
4. applied journal          -> invalid-change, unknown-dependency
5. budget                   -> invalid-budget, budget-exceeded
6. rollback retain          -> invalid-retain

Policy errors (2) outrank every data error (3-4) so a frozen production
request can never be influenced by, or leak details about, its graph.
"""
import heapq

from journal import (JournalError, dedupe, graph, read_applied, read_changes,
                     read_retain)
from policy import PolicyError, limit_for

ENVIRONMENTS = ("staging", "production")
ACTIONS = ("plan", "rollback")


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological(deps):
    """Deterministic execution order over all declared changes.

    Kahn's algorithm with a heap of currently eligible IDs, so ties are broken
    lexicographically by ID rather than by input position (SPEC G1). The full
    order is computed for both actions: rollback needs the reverse of the
    whole order even though it emits only applied entries, which is what makes
    reverse order correct even when an intermediate change is unapplied.
    """
    indegree = {cid: len(needs) for cid, needs in deps.items()}
    dependents = {cid: [] for cid in deps}
    for cid, needs in deps.items():
        for need in needs:
            dependents[need].append(cid)
    ready = [cid for cid, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for follower in dependents[current]:
            indegree[follower] -= 1
            if indegree[follower] == 0:
                heapq.heappush(ready, follower)
    if len(order) != len(deps):
        # Nodes left with a nonzero indegree are exactly those reachable from
        # a cycle; a self-dependency ("a" needs "a") also lands here.
        raise JournalError("dependency-cycle")
    return order


def _retain_closure(retain, deps):
    """Transitive dependencies of the retained set.

    Called only after `read_retain` has proven every retained ID is applied,
    and after the graph is known acyclic, so every walked node is applied too.
    Condition 3 of G2 is therefore satisfied without filtering here.

    Walking iteratively rather than recursively avoids a RecursionError on
    deep dependency chains (a legality concern, not a performance one).
    """
    keep = set()
    pending = list(retain)
    while pending:
        cid = pending.pop()
        for need in deps[cid]:
            if need not in keep:
                keep.add(need)
                pending.append(need)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Compare by membership, never by set lookup: JSON can supply a list
        # or object here, and `[...] in {...}` would raise TypeError instead
        # of producing the required error object.
        environment = request.get("environment")
        if not isinstance(environment, str) or environment not in ENVIRONMENTS:
            raise PolicyError("invalid-environment")
        action = request.get("action")
        if not isinstance(action, str) or action not in ACTIONS:
            raise PolicyError("unsupported-action")
        budget = limit_for(request, action)

        changes = dedupe(read_changes(request.get("changes")))
        deps = graph(changes)
        declared = set(deps)
        for needs in deps.values():
            # A missing target and an applied entry for an undeclared change
            # share one code: the request references an ID it never declared.
            if not needs <= declared:
                raise JournalError("unknown-dependency")
        order = _topological(deps)

        applied_value = request.get("applied")
        if applied_value is None:
            applied_value = []
        applied = read_applied(applied_value)
        if not applied <= declared:
            raise JournalError("unknown-dependency")

        if action == "plan":
            # Already applied entries satisfy dependencies (the graph is over
            # all changes) but their units are never re-charged.
            unapplied = [cid for cid in order if cid not in applied]
            units = sum(row["units"] for row in changes if row["id"] not in applied)
            if units > budget:
                return failure("budget-exceeded")
            return {"status": "ok", "actions": unapplied, "units": units}

        retain = read_retain(request.get("retain"), applied)
        keep = retain | _retain_closure(retain, deps)
        removed = [cid for cid in reversed(order) if cid in applied and cid not in keep]
        removed_ids = set(removed)
        # Rollback units count the actions emitted, i.e. the changes removed;
        # retained changes stay deployed and cost nothing.
        return {"status": "ok", "actions": removed,
                "units": sum(row["units"] for row in changes if row["id"] in removed_ids)}
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

