"""Normalize release records at the input boundary."""
import json


class JournalError(ValueError):
    pass


def _read_id_list(value):
    # Dependency and journal arrays are rejected here, before any graph work, so a
    # malformed shape can never reach the topological sort.
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for item in value:
        if not isinstance(item, str):
            raise JournalError("invalid-change")
    return list(value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    by_id = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = frozenset(_read_id_list(row.get("depends_on", [])))
        change = {"id": row["id"], "component": row["component"],
                  "units": row["units"], "depends_on": depends_on}
        # Replay collapses duplicates only when every accounted field agrees, so a
        # dependency set is compared order-insensitively but still as a whole.
        previous = by_id.get(row["id"])
        if previous is not None:
            if (previous["component"] != change["component"]
                    or previous["units"] != change["units"]
                    or previous["depends_on"] != change["depends_on"]):
                raise JournalError("conflicting-change")
            continue
        by_id[row["id"]] = change
        changes.append(change)
    return changes


def read_applied(value):
    return _read_id_list(value)


def canonical(change):
    """Stable text form so planner output never depends on set iteration order."""
    return json.dumps([change["id"], change["component"], change["units"],
                       sorted(change["depends_on"])], separators=(",", ":"))

