"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, check_budget, limit_for


class PlannerError(ValueError):
    pass


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    # Deterministic order: among all currently eligible changes pick the smallest
    # id, so replaying the same request always yields the same sequence.
    by_id = {change["id"]: change for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            if target not in by_id:
                raise PlannerError("unknown-dependency")
    waiting = {change["id"]: len(change["depends_on"]) for change in changes}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            dependents[target].append(change["id"])
    ready = [cid for cid, count in waiting.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        cid = heapq.heappop(ready)
        order.append(cid)
        for follower in dependents[cid]:
            waiting[follower] -= 1
            if waiting[follower] == 0:
                heapq.heappush(ready, follower)
    if len(order) != len(changes):
        # Detected before any action is emitted, so a cycle never produces a
        # partial plan the caller could mistake for an executable order.
        raise PlannerError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    action = request["action"]
    # Graph failures are domain errors too: the caller gets a JSON result and a
    # zero exit code even for a cycle or a dangling dependency.
    try:
        order = _topological_order(changes)
    except PlannerError as exc:
        return failure(str(exc))
    known = set(order)
    for cid in applied:
        if cid not in known:
            return failure("unknown-dependency")
    applied_set = frozenset(applied)
    units_by_id = {change["id"]: change["units"] for change in changes}
    if action == "rollback":
        selected = [cid for cid in reversed(order) if cid in applied_set]
    else:
        selected = [cid for cid in order if cid not in applied_set]
    units = sum(units_by_id[cid] for cid in selected)
    try:
        check_budget(action, budget, units)
    except PolicyError as exc:
        return failure(str(exc))
    return {"status": "ok", "actions": selected, "units": units}

policy.py.text:
"""Validate release policy before computing actions."""


class PolicyError(ValueError):
    pass


# G1 authorizes both actions in both environments; keeping the set explicit means
# a later goal can narrow it without touching the callers.
ENVIRONMENTS = {"staging", "production"}
ACTIONS = {"plan", "rollback"}


def _label(field, value):
    # Unhashable JSON values (arrays/objects) cannot be tested with `in`, so the
    # type is checked first and only plain strings reach the set membership.
    if not isinstance(value, str) or value not in field:
        return None
    return value


def limit_for(request):
    if _label(ENVIRONMENTS, request.get("environment")) is None:
        raise PolicyError("invalid-environment")
    action = _label(ACTIONS, request.get("action"))
    if action is None:
        raise PolicyError("unsupported-action")
    # bool is a subclass of int, so an exact type test is what excludes it.
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return budget


def check_budget(action, budget, units):
    # Rollback always validates the budget field but never lets it cap output:
    # undoing an applied release must not be blocked by a smaller budget.
    if action == "plan" and units > budget:
        raise PolicyError("budget-exceeded")

